function genPassphrase(words, n, sep, rnd){
  words = words || WORDLIST.split(" "); sep = sep || "-"; rnd = rnd || Math.random;
  if (!words.length) return "";
  var out = [];
  for (var i = 0; i < n; i++) out.push(words[Math.floor(rnd() * words.length)]);
  return out.join(sep);
}
function entropyBits(words, n){
  words = words || WORDLIST.split(" ");
  if (!words.length || n <= 0) return 0;
  return n * (Math.log(words.length) / Math.log(2));
}
var EXPORTS = { WORDLIST: WORDLIST, genPassphrase: genPassphrase, entropyBits: entropyBits };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PassphraseForgePure = EXPORTS; }
